function @@proc@@(p_code in varchar2) return boolean is
  l_hit boolean := false;
begin
  if p_code = @@num@@ then -- @expect
    l_hit := true;
  end if;
  return l_hit;
end @@proc@@;

procedure @@proc@@(p_id in number) is
  l_n number;
begin
  l_n := p_id * 2;
  if l_n = '@@num@@' then -- @expect
    dbms_output.put_line('match');
  end if;
end @@proc@@;

procedure @@proc@@(p_id in number) is
  l_d date;
begin
  select max(created_on) into l_d from @@tab@@ where id = p_id;
  if l_d < '01-JAN-20' then -- @expect
    @@proc2@@(p_id);
  end if;
end @@proc@@;

