function @@proc@@(p_text in varchar2) return date is
  l_d date;
begin
  dbms_output.put_line('parsing ' || p_text);
  l_d := to_date(p_text, 'yyyy-mm-dd');
  dbms_output.put_line('parsed');
  return l_d;
end @@proc@@;

procedure @@proc@@(p_a in number, p_name in varchar2) is
  l_n number := 0;
  l_s varchar2(20) := '@@str2@@';
  l_d date := sysdate;
begin
  if l_n < p_a then
    dbms_output.put_line('below');
  end if;
  if p_name = '@@str@@' then
    dbms_output.put_line('named');
  end if;
  if p_a > 10 and l_s <> p_name then
    dbms_output.put_line('other');
  end if;
end @@proc@@;

procedure @@proc@@(p_id in @@tab@@.id%type, p_name in @@tab@@.@@col@@%type) is
begin
  if p_id = 'none' then
    dbms_output.put_line('no id');
  end if;
  if p_name = 42 then
    dbms_output.put_line('numeric name');
  end if;
end @@proc@@;

function @@proc@@(p_from in date, p_to in date) return boolean is
  l_start date := p_from;
  l_end date := p_to;
begin
  if l_end - l_start < 3 then
    return true;
  end if;
  return false;
end @@proc@@;

function @@proc@@(p_text in varchar2) return timestamp is
  l_d date;
  l_ts timestamp;
begin
  l_d := to_date(p_text, 'Month dd, yyyy');
  l_ts := to_timestamp(to_char(l_d, 'dd Mon, yyyy') || ' 10:00', 'dd Mon, yyyy hh24:mi');
  return l_ts;
end @@proc@@;
